import XCTest
@testable import FormbricksSDK

final class FormbricksWorkspaceTests: XCTestCase {

    override func setUp() {
        super.setUp()
        // Always clean up before each test
        Formbricks.cleanup()
    }

    override func tearDown() {
        Formbricks.cleanup()
        super.tearDown()
    }

    func testBaseApiUrl() {
        // Test that baseApiUrl returns nil when appUrl is nil
        XCTAssertNil(FormbricksWorkspace.baseApiUrl)

        // Setup SDK with valid appUrl
        Formbricks.setup(with: FormbricksConfig.Builder(appUrl: "https://app.formbricks.com", workspaceId: "test-workspace-id")
            .setLogLevel(.debug)
            .build())

        // Test that baseApiUrl returns the correct URL
        XCTAssertEqual(FormbricksWorkspace.baseApiUrl, "https://app.formbricks.com")
    }

    func testSurveyScriptUrlString() {
        // Test that surveyScriptUrlString returns nil when appUrl is nil
        XCTAssertNil(FormbricksWorkspace.surveyScriptUrlString)

        // Setup SDK with valid appUrl
        Formbricks.setup(with: FormbricksConfig.Builder(appUrl: "https://app.formbricks.com", workspaceId: "test-workspace-id")
            .setLogLevel(.debug)
            .build())

        // Test that surveyScriptUrlString returns the correct URL
        XCTAssertEqual(FormbricksWorkspace.surveyScriptUrlString, "https://app.formbricks.com/js/surveys.umd.cjs")

        // Test with invalid URL
        Formbricks.cleanup()
        Formbricks.setup(with: FormbricksConfig.Builder(appUrl: "invalid url", workspaceId: "test-workspace-id")
            .setLogLevel(.debug)
            .build())

        // Test that surveyScriptUrlString returns nil for invalid URL
        XCTAssertNil(FormbricksWorkspace.surveyScriptUrlString)
    }
}

import XCTest
@testable import FormbricksSDK

final class CalendarDaysBetweenTests: XCTestCase {
    private func makeDate(year: Int, month: Int, day: Int, hour: Int = 12, minute: Int = 0, second: Int = 0) -> Date {
        let calendar = Calendar.current
        var comps = DateComponents()
        comps.calendar = calendar
        comps.timeZone = calendar.timeZone
        comps.year = year
        comps.month = month
        comps.day = day
        comps.hour = hour
        comps.minute = minute
        comps.second = second
        return calendar.date(from: comps) ?? Date()
    }

    func testSameDayReturnsZero() {
        let from = makeDate(year: 2025, month: 1, day: 15, hour: 10, minute: 30)
        let to = makeDate(year: 2025, month: 1, day: 15, hour: 22, minute: 15)
        let days = Calendar.current.numberOfDaysBetween(from, and: to)
        XCTAssertEqual(days, 0)
    }

    func testNextDayReturnsOne() {
        let from = makeDate(year: 2025, month: 1, day: 15, hour: 10)
        let to = makeDate(year: 2025, month: 1, day: 16, hour: 9)
        let days = Calendar.current.numberOfDaysBetween(from, and: to)
        XCTAssertEqual(days, 1)
    }

    func testMultipleDays() {
        let from = makeDate(year: 2025, month: 1, day: 10, hour: 10)
        let to = makeDate(year: 2025, month: 1, day: 13, hour: 9)
        let days = Calendar.current.numberOfDaysBetween(from, and: to)
        XCTAssertEqual(days, 3)
    }

    func testReverseOrderClampsToZero() {
        let from = makeDate(year: 2025, month: 1, day: 20, hour: 12)
        let to = makeDate(year: 2025, month: 1, day: 18, hour: 12)
        let days = Calendar.current.numberOfDaysBetween(from, and: to)
        XCTAssertEqual(days, 0)
    }

    func testAcrossMidnightCountsAsOne() {
        let from = makeDate(year: 2025, month: 3, day: 10, hour: 23, minute: 59)
        let to = makeDate(year: 2025, month: 3, day: 11, hour: 0, minute: 1)
        let days = Calendar.current.numberOfDaysBetween(from, and: to)
        XCTAssertEqual(days, 1)
    }
}

import XCTest
@testable import FormbricksSDK

final class AppearanceTests: XCTestCase {

    override func setUp() {
        super.setUp()
        Formbricks.cleanup()
        AppearanceState.set(.light)
    }

    override func tearDown() {
        AppearanceState.set(.light)
        Formbricks.cleanup()
        super.tearDown()
    }

    private func traits(_ style: UIUserInterfaceStyle) -> UITraitCollection {
        UITraitCollection(userInterfaceStyle: style)
    }

    func testDefaultsToLight() {
        XCTAssertEqual(AppearanceState.current, .light)
        XCTAssertEqual(AppearanceState.resolved(traits: traits(.dark)), "light")
    }

    func testSetAppearanceWorksBeforeSetup() {
        XCTAssertFalse(Formbricks.isInitialized)
        Formbricks.setAppearance("dark")
        XCTAssertEqual(AppearanceState.current, .dark)
        XCTAssertEqual(AppearanceState.resolved(traits: traits(.light)), "dark")
    }

    func testSystemFollowsTheAppTheme() {
        Formbricks.setAppearance(.system)
        XCTAssertEqual(AppearanceState.resolved(traits: traits(.dark)), "dark")
        XCTAssertEqual(AppearanceState.resolved(traits: traits(.light)), "light")
    }

    func testUnknownValueFallsBackToLight() {
        Formbricks.setAppearance("dark")
        Formbricks.setAppearance("sepia")
        XCTAssertEqual(AppearanceState.current, .light)
    }

    func testSetupConfigAppliesAppearanceAndLogoutKeepsIt() {
        let config = FormbricksConfig.Builder(appUrl: "https://app.formbricks.com", workspaceId: "ws")
            .set(appearance: .dark)
            .build()
        Formbricks.setup(with: config)
        XCTAssertEqual(AppearanceState.current, .dark)

        Formbricks.logout()
        XCTAssertEqual(AppearanceState.current, .dark)
    }

    func testChangeIsAnnouncedToOpenSurveys() {
        let announced = expectation(forNotification: AppearanceState.didChange, object: nil)
        Formbricks.setAppearance("dark")
        wait(for: [announced], timeout: 1)
    }

    func testSwitchScriptToleratesAnOlderRenderer() {
        XCTAssertEqual(
            AppearanceState.switchScript(for: "dark"),
            "window.formbricksSurveys?.setAppearance?.('dark');")
    }

    // MARK: - Changes made while the survey loads

    func testSurveyRenderedEventDecodes() throws {
        let message = try JSONDecoder().decode(JsMessageData.self, from: Data(#"{"event":"onSurveyRendered"}"#.utf8))
        XCTAssertEqual(message.event, .onSurveyRendered)
    }

    /// The handshake must fire after `renderSurvey`, or a held-back change is sent to no renderer.
    func testHtmlAnnouncesTheRenderAfterRenderSurvey() throws {
        let workspace = try workspace()
        let surveyId = try XCTUnwrap(workspace.data.data.surveys?.first?.id)
        let html = try XCTUnwrap(FormbricksViewModel(workspaceResponse: workspace, surveyId: surveyId).htmlString)
        let render = try XCTUnwrap(html.range(of: "window.formbricksSurveys.renderSurvey(surveyProps);"))
        let rendered = try XCTUnwrap(html.range(of: #"event: "onSurveyRendered""#))
        XCTAssertLessThan(render.upperBound, rendered.lowerBound)
    }

    // MARK: - The app's theme for `.system`

    /// The host app can pin its window dark on a light phone; `.system` must follow the window.
    func testSystemFollowsTheTraitSourceOverride() throws {
        Formbricks.setAppearance(.system)
        let hostWindow = UIWindow(frame: .zero)
        hostWindow.overrideUserInterfaceStyle = .dark
        XCTAssertNotEqual(UIView().traitCollection.userInterfaceStyle, .dark, "precondition: default traits are not dark")

        let workspace = try workspace()
        let surveyId = try XCTUnwrap(workspace.data.data.surveys?.first?.id)
        let viewModel = FormbricksViewModel(workspaceResponse: workspace, surveyId: surveyId, traitSource: hostWindow)
        XCTAssertEqual(viewModel.initialAppearance, "dark")
    }

    func testTraitSourceIsNotRetained() throws {
        let workspace = try workspace()
        let surveyId = try XCTUnwrap(workspace.data.data.surveys?.first?.id)
        var hostWindow: UIWindow? = UIWindow(frame: .zero)
        let viewModel = FormbricksViewModel(workspaceResponse: workspace, surveyId: surveyId, traitSource: hostWindow)
        hostWindow = nil
        XCTAssertNil(viewModel.traitSource)
    }

    private func workspace() throws -> WorkspaceResponse {
        Formbricks.setup(with: FormbricksConfig.Builder(appUrl: "https://example.com", workspaceId: "workspaceId")
            .service(MockFormbricksService())
            .build())
        let url = try XCTUnwrap(Bundle.module.url(forResource: "Environment", withExtension: "json"))
        return try JSONDecoder.iso8601Full.decode(WorkspaceResponse.self, from: Data(contentsOf: url))
    }

    // MARK: - customCss

    func testNoCustomCssSendsNoKey() {
        XCTAssertNil(CustomCss.props(workspace: nil, survey: nil))
        XCTAssertNil(CustomCss.props(workspace: CustomCss(light: "", dark: nil), survey: nil))
    }

    func testCustomCssIsForwardedUntouchedAndEmptyFieldsAreOmitted() {
        let props = CustomCss.props(
            workspace: CustomCss(light: ".a{color:red}", dark: nil),
            survey: CustomCss(light: nil, dark: ".b{margin:0}"))
        XCTAssertEqual(props?["workspace"], ["light": ".a{color:red}"])
        XCTAssertEqual(props?["survey"], ["dark": ".b{margin:0}"])
    }

    func testCustomCssDecodesWithAndWithoutTheKey() throws {
        let with = try JSONDecoder().decode(
            Settings.self,
            from: Data(#"{"customCss":{"light":".a{}"}}"#.utf8))
        XCTAssertEqual(with.customCss, CustomCss(light: ".a{}", dark: nil))

        let without = try JSONDecoder().decode(Settings.self, from: Data("{}".utf8))
        XCTAssertNil(without.customCss)
    }
}

import XCTest
@testable import FormbricksSDK

/// The no-overlay presentation path: the survey's own window, and which overlay picks that path.
///
/// Tests run without a window scene, so `present` itself can only reach its guard here. The window
/// wiring is driven through `installPassthroughWindow` with a frame-based window instead.
final class PassthroughPresentationTests: XCTestCase {
    let workspaceId = "workspaceId"
    let appUrl = "https://example.com"
    let surveyID = "cm6ovw6j7000gsf0kduf4oo4i"
    let mockService = MockFormbricksService()

    override func setUp() {
        super.setUp()
        Formbricks.cleanup()
        clearPersistedWorkspaceCache()
    }

    override func tearDown() {
        Formbricks.cleanup()
        clearPersistedWorkspaceCache()
        super.tearDown()
    }

    private func clearPersistedWorkspaceCache() {
        UserDefaults.standard.removeObject(forKey: SurveyManager.workspaceResponseObjectKey)
        UserDefaults.standard.removeObject(forKey: SurveyManager.legacyEnvironmentResponseObjectKey)
    }

    /// Sets the SDK up against `Environment.json`, whose workspace overlay is `none` and whose
    /// `surveyID` survey overrides it to `dark`.
    private func loadWorkspace() -> WorkspaceResponse? {
        let config = FormbricksConfig.Builder(appUrl: appUrl, workspaceId: workspaceId)
            .service(mockService)
            .build()
        Formbricks.setup(with: config)
        Formbricks.surveyManager?.refreshWorkspaceIfNeeded(force: true)
        let loaded = expectation(description: "Workspace loaded")
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { loaded.fulfill() }
        wait(for: [loaded])
        return Formbricks.surveyManager?.workspaceResponse
    }

    // MARK: - Passthrough window

    func testPassthroughWindowShowsAboveTheAppAndBlocksUntilACardIsReported() throws {
        let workspace = try XCTUnwrap(loadWorkspace())
        let window = PassthroughWindow(frame: CGRect(x: 0, y: 0, width: 400, height: 800))

        PresentSurveyManager().installPassthroughWindow(
            window, workspaceResponse: workspace, id: surveyID)

        XCTAssertFalse(window.isHidden)
        XCTAssertEqual(window.windowLevel, .normal + 1)
        XCTAssertFalse(window.isOpaque)
        XCTAssertNotNil(window.rootViewController)
        // No rect yet — or never, from an older server — so it blocks like the SDK always did.
        XCTAssertEqual(window.touchRegion, .everything)
    }

    func testReportedCardRectDecidesWhichTouchesTheWindowTakes() throws {
        let workspace = try XCTUnwrap(loadWorkspace())
        let window = PassthroughWindow(frame: CGRect(x: 0, y: 0, width: 400, height: 800))
        let relay = PresentSurveyManager().installPassthroughWindow(
            window, workspaceResponse: workspace, id: surveyID)

        relay.onCardRectChange?(CardRect(x: 16, y: 500, width: 368, height: 280))
        XCTAssertEqual(window.touchRegion, .card(CGRect(x: 16, y: 500, width: 368, height: 280)))

        // Card animating out: nothing on screen, so nothing is claimed.
        relay.onCardRectChange?(nil)
        XCTAssertEqual(window.touchRegion, .nothing)
    }

    func testDismissTearsTheWindowDown() throws {
        let workspace = try XCTUnwrap(loadWorkspace())
        let window = PassthroughWindow(frame: CGRect(x: 0, y: 0, width: 400, height: 800))
        let manager = PresentSurveyManager()
        manager.installPassthroughWindow(window, workspaceResponse: workspace, id: surveyID)

        // On the main thread, so the teardown runs synchronously.
        manager.dismissView()

        XCTAssertTrue(window.isHidden, "a leftover window would sit invisibly over the app")
        XCTAssertNil(window.rootViewController)
    }

    func testOverlayPresentAbortsWithoutAKeyWindow() throws {
        let workspace = try XCTUnwrap(loadWorkspace())
        let done = expectation(description: "Present completes")
        // Held for the whole test: `present` hops to the main queue holding `self` weakly.
        let manager = PresentSurveyManager()

        manager.present(workspaceResponse: workspace, id: surveyID, overlay: .dark) { success in
            XCTAssertFalse(success)
            done.fulfill()
        }
        wait(for: [done], timeout: 2.0)
    }

    // MARK: - Modal path (light / dark overlay)

    /// A visible window whose root is `root`, handed to the manager in place of the scene lookup.
    private func manager(presentingIn root: UIViewController) -> (PresentSurveyManager, UIWindow) {
        let window = UIWindow(frame: CGRect(x: 0, y: 0, width: 400, height: 800))
        window.rootViewController = root
        window.makeKeyAndVisible()
        // Lay the container views out now: UIKit refuses to present from a view not yet in a window.
        window.layoutIfNeeded()
        let manager = PresentSurveyManager()
        manager.keyWindow = { window }
        return (manager, window)
    }

    func testOverlaySurveyIsPresentedOnTheTopMostViewController() throws {
        let workspace = try XCTUnwrap(loadWorkspace())
        // Tab bar -> navigation stack -> leaf: the walker has to go through both containers.
        let leaf = UIViewController()
        let tabs = UITabBarController()
        tabs.viewControllers = [UINavigationController(rootViewController: leaf)]
        let (manager, window) = manager(presentingIn: tabs)
        // Waits on the presentation itself: the test runner's scene is never foreground-active, so
        // UIKit sets `presentedViewController` but never calls the presentation's completion.
        let presented = expectation(
            for: NSPredicate { _, _ in leaf.presentedViewController != nil }, evaluatedWith: nil)

        manager.present(workspaceResponse: workspace, id: surveyID, overlay: .dark)
        wait(for: [presented], timeout: 3.0)

        manager.dismissView()
        withExtendedLifetime(window) {}
    }

    func testOverlaySurveyIsNotPresentedOverAnAlert() throws {
        let workspace = try XCTUnwrap(loadWorkspace())
        let alert = UIAlertController(title: "Busy", message: nil, preferredStyle: .alert)
        let (manager, window) = manager(presentingIn: alert)
        let done = expectation(description: "Present completes")

        manager.present(workspaceResponse: workspace, id: surveyID, overlay: .light) { success in
            XCTAssertFalse(success, "UIKit cannot host a modal on an alert")
            done.fulfill()
        }
        wait(for: [done], timeout: 2.0)
        withExtendedLifetime(window) {}
    }

    func testNoOverlaySurveyGetsItsOwnWindowInsteadOfAModal() throws {
        let workspace = try XCTUnwrap(loadWorkspace())
        let root = UIViewController()
        let (manager, window) = manager(presentingIn: root)
        let done = expectation(description: "Present completes")

        manager.present(workspaceResponse: workspace, id: surveyID, overlay: .none) { success in
            XCTAssertTrue(success)
            done.fulfill()
        }
        wait(for: [done], timeout: 2.0)

        // Not a presented view controller: that would answer the hit test for the whole screen.
        XCTAssertNil(root.presentedViewController)
        let surveyWindow = window.windowScene?.windows.first { $0 is PassthroughWindow }
        XCTAssertEqual(surveyWindow?.windowLevel, .normal + 1)

        manager.dismissView()
        XCTAssertEqual(surveyWindow?.isHidden, true)
    }

    // MARK: - Overlay resolution

    func testSurveyOverlayOverrideWinsOverTheWorkspaceSetting() throws {
        let workspace = try XCTUnwrap(loadWorkspace())
        let manager = try XCTUnwrap(Formbricks.surveyManager)
        let survey = workspace.data.data.surveys?.first { $0.id == surveyID }

        XCTAssertEqual(manager.resolveOverlay(for: survey), .dark)
    }

    func testWithoutASurveyOverrideTheWorkspaceSettingApplies() throws {
        _ = try XCTUnwrap(loadWorkspace())
        let manager = try XCTUnwrap(Formbricks.surveyManager)

        XCTAssertEqual(manager.resolveOverlay(for: nil), .none)
    }

    func testWithNoWorkspaceStateTheOverlayDefaultsToNone() {
        let manager = SurveyManager.create(
            userManager: UserManager(), presentSurveyManager: PresentSurveyManager(),
            service: mockService)

        XCTAssertNil(manager.workspaceResponse)
        XCTAssertEqual(manager.resolveOverlay(for: nil), .none)
    }
}

import UIKit
import WebKit
import XCTest
@testable import FormbricksSDK

/// WKWebView ignores Dynamic Type, so the SDK hands the user's setting to the survey page itself
/// (ENG-3427). These pin what a respondent can see: the default size renders exactly as before, the
/// text follows the setting in both directions, and the accessibility sizes stop at the cap the
/// survey layout is known to fit.
final class SurveyTextScaleTests: XCTestCase {

    /// Every Dynamic Type setting, smallest to largest.
    private let categories: [UIContentSizeCategory] = [
        .extraSmall, .small, .medium, .large, .extraLarge, .extraExtraLarge, .extraExtraExtraLarge,
        .accessibilityMedium, .accessibilityLarge, .accessibilityExtraLarge,
        .accessibilityExtraExtraLarge, .accessibilityExtraExtraExtraLarge,
    ]

    func testTheDefaultSizeLeavesThePageUntouched() {
        XCTAssertEqual(SurveyTextScale.factor(for: .large), 1)
        XCTAssertEqual(SurveyTextScale.textSizeAdjust(for: .large), "auto")
        XCTAssertEqual(SurveyTextScale.textSizeAdjust(for: .unspecified), "auto",
                       "A trait collection with no setting must read as the default size")
    }

    func testTheTextFollowsTheSettingInBothDirections() {
        let factors = categories.map(SurveyTextScale.factor(for:))
        XCTAssertEqual(factors, factors.sorted(), "A larger setting must never make the text smaller")
        XCTAssertLessThan(SurveyTextScale.factor(for: .extraSmall), 1)
        let largestStandardSize = SurveyTextScale.factor(for: .extraExtraExtraLarge)
        XCTAssertTrue(largestStandardSize > 1 && largestStandardSize < SurveyTextScale.maximumFactor,
                      "The largest non-accessibility size must grow the text without reaching the cap")
    }

    func testTheAccessibilitySizesStopAtTheCap() {
        XCTAssertTrue(categories.allSatisfy { SurveyTextScale.factor(for: $0) <= SurveyTextScale.maximumFactor })
        XCTAssertEqual(SurveyTextScale.textSizeAdjust(for: .accessibilityExtraExtraExtraLarge), "200%")
    }

    /// The setting has to reach the page's root element, or WebKit never applies it. It comes from the
    /// presenting window's traits, so a host app that overrides Dynamic Type there sizes the survey too.
    func testTheSurveyPageCarriesThePresentersSetting() throws {
        guard #available(iOS 17.0, *) else { throw XCTSkip("traitOverrides needs iOS 17") }
        let workspace = try setUpWorkspace()

        func html(presentedFrom traitSource: UITraitEnvironment?) throws -> String {
            try XCTUnwrap(FormbricksViewModel(
                workspaceResponse: workspace, surveyId: surveyId, traitSource: traitSource
            ).htmlString)
        }
        // Both directions, so the assertions hold whatever the simulator's own setting is.
        let largest = UIWindow(frame: .zero)
        largest.traitOverrides.preferredContentSizeCategory = .accessibilityExtraExtraExtraLarge
        let smallest = UIWindow(frame: .zero)
        smallest.traitOverrides.preferredContentSizeCategory = .extraSmall

        XCTAssertTrue(try html(presentedFrom: largest).contains("-webkit-text-size-adjust: 200%"))
        XCTAssertTrue(try html(presentedFrom: smallest).contains(
            "-webkit-text-size-adjust: \(SurveyTextScale.textSizeAdjust(for: .extraSmall))"))
        XCTAssertTrue(try html(presentedFrom: nil).contains("-webkit-text-size-adjust: auto"),
                      "Without a presenter the page must not depend on the device's setting")
    }

    /// WebKit ignores the percentage in desktop-class content mode, which full-size iPads would
    /// otherwise load the survey in.
    func testTheSurveyWebViewAsksForMobileContent() throws {
        let workspace = try setUpWorkspace()
        let window = PassthroughWindow(frame: CGRect(x: 0, y: 0, width: 400, height: 800))
        let manager = PresentSurveyManager()
        manager.installPassthroughWindow(window, workspaceResponse: workspace, id: surveyId)
        addTeardownBlock { manager.dismissView() }
        window.layoutIfNeeded()

        let webView = try XCTUnwrap(firstWebView(in: window))
        XCTAssertEqual(webView.configuration.defaultWebpagePreferences.preferredContentMode, .mobile)
    }

    private let surveyId = "cm6ovw6j7000gsf0kduf4oo4i"

    /// Sets the SDK up for building a survey page, and tears it down after the test.
    private func setUpWorkspace() throws -> WorkspaceResponse {
        Formbricks.cleanup()
        addTeardownBlock { Formbricks.cleanup() }
        Formbricks.setup(with: FormbricksConfig.Builder(appUrl: "https://example.com", workspaceId: "workspaceId")
            .service(MockFormbricksService())
            .build())
        let fixtureUrl = try XCTUnwrap(Bundle.module.url(forResource: "Environment", withExtension: "json"))
        return try JSONDecoder.iso8601Full.decode(WorkspaceResponse.self, from: Data(contentsOf: fixtureUrl))
    }

    private func firstWebView(in view: UIView) -> WKWebView? {
        (view as? WKWebView) ?? view.subviews.lazy.compactMap(firstWebView(in:)).first
    }
}

import XCTest
@testable import FormbricksSDK

/// The Embedded Data bag (ENG-1844 / ENG-2472): host-supplied context attached to future responses
/// without tying it to a trigger. These pin the contract the four SDKs share, so a divergence here
/// is a divergence from the JS SDK too.
final class EmbeddedDataTests: XCTestCase {

    override func setUp() {
        super.setUp()
        Formbricks.cleanup()
        clearPersistedUserId()
        EmbeddedDataManager.shared.removeAll()
    }

    override func tearDown() {
        clearPersistedUserId()
        EmbeddedDataManager.shared.removeAll()
        Formbricks.cleanup()
        super.tearDown()
    }

    /// Removes a seeded identity on both sides of every test.
    ///
    /// `Formbricks.cleanup()` clears it only when a `UserManager` exists to log out, which it does
    /// not before the first `setup`. Without this, a seeded id would outlive this class — which
    /// runs first alphabetically — and `FormbricksSDKTests` asserts `userManager?.userId` is nil
    /// before setup.
    private func clearPersistedUserId() {
        UserDefaults.standard.removeObject(forKey: "userIdKey")
    }

    /// Initializes the SDK against the mock service, so identity changes can be exercised without
    /// the network.
    private func setUpSdk() {
        Formbricks.setup(
            with: FormbricksConfig.Builder(appUrl: "https://app.formbricks.com", workspaceId: "ws-1")
                .setLogLevel(.debug)
                .service(MockFormbricksService())
                .build())
    }

    /// Seeds a persisted identity, the way a previous app session would have left one.
    ///
    /// Not `Formbricks.setUserId`: that only enqueues into the debounced `UpdateQueue`, so
    /// `userManager?.userId` stays nil until a network sync lands, and a test driving it that way
    /// would silently take the first-identification branch and pass for the wrong reason. Writing
    /// the same `UserDefaults` key the getter falls back to is exact, needs no timer or request, and
    /// models the honest scenario — the app relaunches already identified, then a different user
    /// signs in.
    ///
    /// Must be called **before** `setUpSdk()`: `UserManager` caches `backingUserId` on first read,
    /// so the value has to be in place when the fresh manager is created. The key is
    /// `UserManager`'s own private constant, repeated here because that is the storage contract
    /// this seeds.
    private func seedPersistedUserId(_ userId: String) {
        UserDefaults.standard.set(userId, forKey: "userIdKey")
    }

    /// `snapshot()` returns `[String: Any]`, so comparisons go through `NSDictionary`, which
    /// compares element-wise with the bridged equality each value type already has.
    private func assertSnapshot(_ expected: [String: Any], file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertEqual(
            EmbeddedDataManager.shared.snapshot() as NSDictionary,
            expected as NSDictionary,
            file: file,
            line: line
        )
    }

    // MARK: - Merge semantics

    func testMergesInsteadOfReplacing() {
        Formbricks.setEmbeddedData(["plan": "pro", "screen": "product"])
        Formbricks.setEmbeddedData(["screen": "checkout"])

        assertSnapshot(["plan": "pro", "screen": "checkout"])
    }

    func testNilRemovesTheKey() {
        Formbricks.setEmbeddedData(["plan": "pro", "screen": "product"])
        Formbricks.setEmbeddedData(["screen": nil])

        assertSnapshot(["plan": "pro"])
    }

    func testLastWriteWinsPerKey() {
        Formbricks.setEmbeddedData(["plan": "free"])
        Formbricks.setEmbeddedData(["plan": "pro"])

        assertSnapshot(["plan": "pro"])
    }

    func testOmittedKeysAreUntouched() {
        // Swift has no `undefined`, so "skip this field" is spelled by leaving the key out — and
        // that must not disturb what an earlier call set. `nil` is the explicit "remove" spelling.
        Formbricks.setEmbeddedData(["plan": "pro", "screen": "product"])
        Formbricks.setEmbeddedData(["seats": 4])

        assertSnapshot(["plan": "pro", "screen": "product", "seats": 4.0])
    }

    // MARK: - Clearing

    func testClearOneKeyLeavesTheRest() {
        Formbricks.setEmbeddedData(["plan": "pro", "screen": "product", "seats": 4])

        Formbricks.clearEmbeddedData("screen")

        assertSnapshot(["plan": "pro", "seats": 4.0])
    }

    func testClearingAnUnsetKeyIsANoOp() {
        Formbricks.setEmbeddedData(["plan": "pro"])

        Formbricks.clearEmbeddedData("neverSet")

        assertSnapshot(["plan": "pro"])
    }

    func testClearEverything() {
        Formbricks.setEmbeddedData(["plan": "pro", "screen": "product"])

        Formbricks.clearEmbeddedData()

        assertSnapshot([:])
    }

    // MARK: - Value types

    func testEveryScalarSurvivesInItsJsonForm() {
        let signedUpAt = Date(timeIntervalSince1970: 1_787_000_000)

        Formbricks.setEmbeddedData([
            "plan": "pro",
            "seats": 25,
            "score": 9.5,
            "isTrial": false,
            "signedUpAt": .date(signedUpAt),
        ])

        let snapshot = EmbeddedDataManager.shared.snapshot()
        XCTAssertEqual(snapshot["plan"] as? String, "pro")
        XCTAssertEqual(snapshot["seats"] as? Double, 25)
        XCTAssertEqual(snapshot["score"] as? Double, 9.5)
        XCTAssertEqual(snapshot["isTrial"] as? Bool, false)
        // ISO 8601 is what the renderer's ingest contract accepts for a `date` field.
        XCTAssertEqual(snapshot["signedUpAt"] as? String, ISO8601DateFormatter().string(from: signedUpAt))
    }

    func testASnapshotIsSerializableAsJson() {
        // The snapshot is embedded in the survey WebView's props blob, which goes through
        // JSONSerialization. If it ever threw, the failure would not be a missing field — it would
        // be no survey at all.
        Formbricks.setEmbeddedData([
            "plan": "pro",
            "seats": 25,
            "isTrial": true,
            "signedUpAt": .date(Date()),
        ])

        XCTAssertTrue(JSONSerialization.isValidJSONObject(EmbeddedDataManager.shared.snapshot()))
        XCTAssertNoThrow(
            try JSONSerialization.data(withJSONObject: EmbeddedDataManager.shared.snapshot(), options: []))
    }

    func testANonFiniteNumberIsSkippedRatherThanCostingTheSurvey() {
        // THE guard: JSONSerialization throws on a non-finite Double, and the payload it would
        // refuse is the whole survey's props blob. Dropping the key is the only safe answer.
        Formbricks.setEmbeddedData(["plan": "pro"])

        Formbricks.setEmbeddedData([
            "broken": .number(Double.nan),
            "alsoBroken": .number(Double.infinity),
        ])

        assertSnapshot(["plan": "pro"])
        XCTAssertTrue(JSONSerialization.isValidJSONObject(EmbeddedDataManager.shared.snapshot()))
    }

    // MARK: - Lifetime

    func testSnapshotIsDetachedFromLaterWrites() {
        // What "a value set after a survey is displayed does not change that response" rests on:
        // the WebView payload holds this dictionary for the life of the survey.
        Formbricks.setEmbeddedData(["plan": "pro"])
        let snapshot = EmbeddedDataManager.shared.snapshot()

        Formbricks.setEmbeddedData(["plan": "enterprise", "extra": "later"])

        XCTAssertEqual(snapshot as NSDictionary, ["plan": "pro"] as NSDictionary)
    }

    func testWorksBeforeSetup() {
        // Deliberately unlike the other public methods: a host that pushes context at launch must
        // not have the value dropped because initialization had not finished yet.
        XCTAssertFalse(Formbricks.isInitialized)

        Formbricks.setEmbeddedData(["plan": "pro"])

        assertSnapshot(["plan": "pro"])
    }

    func testIsNotPersisted() {
        // A cold start begins empty. Nothing host-supplied may reach UserDefaults, where it would
        // outlive the session and blur the Embedded Data ↔ contact-attribute boundary. A UUID
        // marker so the search cannot collide with unrelated defaults.
        let marker = "fb-embedded-probe-\(UUID().uuidString)"

        Formbricks.setEmbeddedData(["probe": .string(marker)])

        // Only the marker is asserted, deliberately: comparing the whole key set would also catch a
        // write from some earlier test's in-flight sync and fail for a reason this test is not about.
        let defaults = UserDefaults.standard.dictionaryRepresentation()
        XCTAssertFalse(defaults.values.contains { String(describing: $0).contains(marker) })
    }

    func testCleanupClearsTheBag() {
        Formbricks.setEmbeddedData(["plan": "pro"])

        Formbricks.cleanup()

        assertSnapshot([:])
    }

    // MARK: - Identity changes

    func testSwitchingUserClearsTheBag() {
        seedPersistedUserId("user-a")
        setUpSdk()
        XCTAssertEqual(Formbricks.userManager?.userId, "user-a")
        Formbricks.setEmbeddedData(["plan": "pro"])

        Formbricks.setUserId("user-b")

        assertSnapshot([:])
    }

    func testFirstIdentificationKeepsTheBag() {
        // The host pushes context before it knows who the user is — that is the normal order, and
        // clearing here would throw away the value the API exists to carry.
        setUpSdk()
        // `userId` is persisted in UserDefaults, so an id left by an earlier test would make this
        // take the switch branch. Log out first — which also empties the bag, hence the ordering.
        Formbricks.logout()
        XCTAssertNil(Formbricks.userManager?.userId)
        Formbricks.setEmbeddedData(["plan": "pro"])

        Formbricks.setUserId("user-a")

        assertSnapshot(["plan": "pro"])
    }

    func testSettingTheSameUserIdKeepsTheBag() {
        seedPersistedUserId("user-a")
        setUpSdk()
        XCTAssertEqual(Formbricks.userManager?.userId, "user-a")
        Formbricks.setEmbeddedData(["plan": "pro"])

        Formbricks.setUserId("user-a")

        assertSnapshot(["plan": "pro"])
    }

    func testLogoutClearsTheBag() {
        setUpSdk()
        Formbricks.setEmbeddedData(["plan": "pro"])

        Formbricks.logout()

        assertSnapshot([:])
    }

    // MARK: - The debug success trace

    func testTheSuccessTraceNamesKeysAndNeverValues() {
        // The bag is otherwise invisible — memory-only, no getter — so this trace is a host's only
        // confirmation that a write landed. Its one hard rule: the documented use of this bag
        // includes hashed identity fields, so a value must never reach a log line.
        let message = EmbeddedDataManager.setTrace(
            set: ["plan", "hashedEmail"], removed: ["screen"], held: ["hashedEmail", "plan"])

        XCTAssertTrue(message.contains("set [hashedEmail, plan]"))
        XCTAssertTrue(message.contains("removed [screen]"))
        XCTAssertTrue(message.contains("the bag now holds [hashedEmail, plan]"))
        XCTAssertTrue(message.contains("only if the survey declares them"))
    }

    func testTheSuccessTraceOmitsTheRemovedListWhenNothingWasRemoved() {
        let message = EmbeddedDataManager.setTrace(set: ["plan"], removed: [], held: ["plan"])

        XCTAssertFalse(message.contains("removed"))
    }

    func testTheSuccessTraceIsStableAcrossCalls() {
        // Swift dictionaries iterate in an unspecified order that varies per process, so the trace
        // sorts every list. Without that, the same bag would print differently run to run.
        let first = EmbeddedDataManager.setTrace(
            set: ["b", "a", "c"], removed: [], held: ["c", "a", "b"])
        let second = EmbeddedDataManager.setTrace(
            set: ["c", "b", "a"], removed: [], held: ["a", "b", "c"])

        XCTAssertEqual(first, second)
        XCTAssertTrue(first.contains("set [a, b, c]"))
    }

    // MARK: - Thread safety

    func testConcurrentWritesDoNotCrash() {
        // The host may call from any thread while the main queue reads the snapshot to present a
        // survey. Without the serial queue this trips the dictionary's exclusivity checks.
        let iterations = 200
        let done = expectation(description: "concurrent writes")
        done.expectedFulfillmentCount = iterations

        DispatchQueue.concurrentPerform(iterations: iterations) { index in
            Formbricks.setEmbeddedData(["key\(index % 8)": .number(Double(index))])
            _ = EmbeddedDataManager.shared.snapshot()
            done.fulfill()
        }

        wait(for: [done], timeout: 10)
        XCTAssertFalse(EmbeddedDataManager.shared.snapshot().isEmpty)
    }
}

import WebKit
import XCTest
@testable import FormbricksSDK

/// A transparent full-screen WebView still swallows every touch — `pointer-events: none` is a web
/// hit test that UIKit never sees. These pin which touches the survey claims in each overlay mode,
/// because getting it wrong is invisible in code review and obvious to a user: either the host app
/// freezes, or the survey itself stops responding.
final class SurveyTouchRegionTests: XCTestCase {

    private let card = CGRect(x: 0, y: 600, width: 390, height: 240)
    private var insideCard: CGPoint { CGPoint(x: 195, y: 700) }
    private var outsideCard: CGPoint { CGPoint(x: 195, y: 200) }

    // MARK: - overlay: light / dark

    /// A visible backdrop is meant to block the host app, so the survey claims the whole screen.
    func testAnOverlaidSurveyClaimsEveryTouch() {
        let region = SurveyTouchRegion.everything

        XCTAssertTrue(region.accepts(insideCard))
        XCTAssertTrue(region.accepts(outsideCard))
        XCTAssertTrue(region.accepts(.zero))
    }

    // MARK: - overlay: none

    /// The card takes its own touches; everything else falls through to the host app.
    func testANoOverlaySurveyClaimsOnlyTheCard() {
        let region = SurveyTouchRegion.forReported(
            rect: CardRect(x: 0, y: 600, width: 390, height: 240))

        XCTAssertEqual(region, .card(card))
        XCTAssertTrue(region.accepts(insideCard), "The survey must stay usable")
        XCTAssertFalse(region.accepts(outsideCard), "The host app must stay usable")
    }

    /// The renderer reports the card's absence, and the SDK must stop claiming touches at that
    /// point. The card is hidden for a full second before `onClose` arrives, so without this the
    /// SDK leaves a dead patch over a host app that looks perfectly usable.
    func testNoCardOnScreenClaimsNothing() {
        let region = SurveyTouchRegion.forReported(rect: nil)

        XCTAssertEqual(region, .nothing)
        XCTAssertFalse(region.accepts(insideCard))
        XCTAssertFalse(region.accepts(outsideCard))
    }

    /// An older self-hosted server serves a renderer that never calls `onCardRectChange`, so no
    /// rect ever arrives. The SDK has to keep behaving exactly as it used to rather than guess.
    ///
    /// This is the distinction the Flutter SDK got wrong: there, a missing rect meant "claim
    /// nothing", so when its DOM probe stopped matching, the survey became untappable. Absence of a
    /// card and absence of the feature are different things.
    func testTheDefaultBeforeAnyRectArrivesBlocksLikeBefore() {
        let window = PassthroughWindow(frame: .zero)

        XCTAssertEqual(window.touchRegion, .everything)
        XCTAssertTrue(window.touchRegion.accepts(outsideCard))
    }

    // MARK: - Boundaries

    /// `CGRect.contains` excludes the far edges, so a tap on the card's bottom-right corner pixel
    /// belongs to the host app. Pinned because a future switch to `insetBy` or a rounding change
    /// would move this silently.
    func testCardEdgesFollowCGRectContains() {
        let region = SurveyTouchRegion.card(card)

        XCTAssertTrue(region.accepts(CGPoint(x: card.minX, y: card.minY)), "Top-left is inside")
        XCTAssertFalse(region.accepts(CGPoint(x: card.maxX, y: card.maxY)), "Bottom-right is not")
        XCTAssertFalse(region.accepts(CGPoint(x: card.minX - 1, y: card.minY)))
    }

    /// A zero-area rect would claim nothing anyway, but the renderer already reports absence rather
    /// than a degenerate rect — assert the mapping keeps its shape if that ever changes.
    func testAZeroAreaCardClaimsNothing() {
        let region = SurveyTouchRegion.forReported(rect: CardRect(x: 10, y: 10, width: 0, height: 0))

        XCTAssertFalse(region.accepts(CGPoint(x: 10, y: 10)))
    }

    // MARK: - Decoding the bridge payload

    /// The rect arrives as JSON over the JS bridge, so the decode is part of the contract.
    func testDecodesAReportedRect() throws {
        let json = #"{"event":"onCardRectChange","rect":{"x":12.5,"y":600,"width":390,"height":240.25}}"#
        let message = try JSONDecoder().decode(CardRectMessage.self, from: Data(json.utf8))

        XCTAssertEqual(message.rect?.cgRect, CGRect(x: 12.5, y: 600, width: 390, height: 240.25))
    }

    /// `rect: null` is how the renderer says the card has gone. It must decode, not throw — a throw
    /// would leave the SDK masking touches to a card that is no longer there.
    func testDecodesAnAbsentRect() throws {
        let json = #"{"event":"onCardRectChange","rect":null}"#
        let message = try JSONDecoder().decode(CardRectMessage.self, from: Data(json.utf8))

        XCTAssertNil(message.rect)
        XCTAssertEqual(SurveyTouchRegion.forReported(rect: message.rect), .nothing)
    }

    /// A payload that does not decode is not "the card left the screen". Forwarding it as `nil`
    /// would make the visible card untappable, so the relay must not hear about it at all.
    func testIgnoresACardRectPayloadThatDoesNotDecode() {
        let relay = SurveyLayoutRelay()
        var reported: [CardRect?] = []
        relay.onCardRectChange = { reported.append($0) }
        let handler = JsMessageHandler(surveyId: "survey", layoutRelay: relay)
        let controller = WKUserContentController()

        handler.userContentController(
            controller,
            didReceive: FakeScriptMessage(
                payload: #"{"event":"onCardRectChange","rect":{"x":"12","y":600,"width":390,"height":240}}"#
            )
        )
        XCTAssertTrue(reported.isEmpty)

        // The same bridge still forwards a well-formed "no card" report.
        handler.userContentController(
            controller,
            didReceive: FakeScriptMessage(payload: #"{"event":"onCardRectChange","rect":null}"#)
        )
        XCTAssertEqual(reported.count, 1)
        XCTAssertNil(reported.first ?? nil)
    }

    // MARK: - PassthroughWindow hit testing

    /// `nil` from `hitTest` is what hands a touch to the host app's window, so this is the fix itself.
    func testPassthroughWindowOnlyClaimsTouchesOnTheCard() {
        let window = PassthroughWindow(frame: CGRect(x: 0, y: 0, width: 400, height: 800))
        window.isHidden = false
        window.touchRegion = .card(CGRect(x: 16, y: 500, width: 368, height: 280))

        XCTAssertNotNil(window.hitTest(CGPoint(x: 200, y: 600), with: nil))
        XCTAssertNil(window.hitTest(CGPoint(x: 200, y: 100), with: nil))

        window.touchRegion = .nothing
        XCTAssertNil(window.hitTest(CGPoint(x: 200, y: 600), with: nil))
    }
}

import XCTest
import WebKit
@testable import FormbricksSDK

final class FormbricksSDKTests: XCTestCase {
    let workspaceId = "workspaceId"
    let appUrl = "https://example.com"
    let userId = "6CCCE716-6783-4D0F-8344-9C7DFA43D8F7"
    let surveyID = "cm6ovw6j7000gsf0kduf4oo4i"
    let mockService = MockFormbricksService()
    let waitDescription = "wait for a second"

    override func setUp() {
        super.setUp()
        // Always clean up before each test
        Formbricks.cleanup()
        clearPersistedWorkspaceCache()
   }

    override func tearDown() {
        Formbricks.cleanup()
        clearPersistedWorkspaceCache()
        super.tearDown()
    }

    /// Removes the cached workspace blobs from UserDefaults so tests don't leak
    /// cache state into each other. `Formbricks.cleanup()` intentionally does
    /// not wipe these keys because real apps rely on the cache across launches.
    private func clearPersistedWorkspaceCache() {
        let defaults = UserDefaults.standard
        defaults.removeObject(forKey: SurveyManager.workspaceResponseObjectKey)
        defaults.removeObject(forKey: SurveyManager.legacyEnvironmentResponseObjectKey)
    }

    func testFormbricks() throws {
        // Everything should be in the default state before initialization.
        XCTAssertFalse(Formbricks.isInitialized)
        XCTAssertNil(Formbricks.surveyManager)
        XCTAssertNil(Formbricks.userManager)

        // The language should be "default" initially
        XCTAssertEqual(Formbricks.language, "default")

        // Set language before SDK setup
        Formbricks.setLanguage("de")
        XCTAssertEqual(Formbricks.language, "de") // This works without initialization

        // User manager default state: there is no user yet.
        XCTAssertNil(Formbricks.userManager?.displays)
        XCTAssertNil(Formbricks.userManager?.responses)
        XCTAssertNil(Formbricks.userManager?.segments)

        // Use methods before init should have no effect except language.
        Formbricks.setUserId("userId")
        Formbricks.setAttributes(["testA" : "testB"])
        Formbricks.setAttribute("test", forKey: "testKey")
        XCTAssertNil(Formbricks.userManager?.userId)

        // Setup the SDK using your new instance-based design.
        // This creates new instances for both the UserManager and SurveyManager.
        Formbricks.setup(with: FormbricksConfig.Builder(appUrl: appUrl, workspaceId: workspaceId)
            .set(attributes: ["a": "b"])
            .add(attribute: "test", forKey: "key")
            .setLogLevel(.debug)
            .service(mockService)
            .build()
        )

        XCTAssertTrue(Formbricks.isInitialized)
        XCTAssertEqual(Formbricks.appUrl, appUrl)
        XCTAssertEqual(Formbricks.workspaceId, workspaceId)

        // Check error state handling.
        XCTAssertFalse(Formbricks.surveyManager?.hasApiError ?? false)

        mockService.isErrorResponseNeeded = true
        Formbricks.surveyManager?.refreshWorkspaceIfNeeded(force: true)
        XCTAssertTrue(Formbricks.surveyManager?.hasApiError ?? false)

        mockService.isErrorResponseNeeded = false
        Formbricks.surveyManager?.refreshWorkspaceIfNeeded(force: true)

        // Wait for environment to refresh
        let refreshExpectation = expectation(description: "Environment refreshed")
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
            refreshExpectation.fulfill()
        }
        wait(for: [refreshExpectation])

        // Authenticate the user.
        Formbricks.setUserId(userId)

        // Wait for user ID to be set with a longer timeout
        let userSetExpectation = expectation(description: "User set")
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) {
            userSetExpectation.fulfill()
        }
        wait(for: [userSetExpectation], timeout: 3.0)

        // Verify user ID is set
        XCTAssertEqual(Formbricks.userManager?.userId, userId, "User ID should be set")
        // User refresh timer should be set.
        XCTAssertNotNil(Formbricks.userManager?.syncTimer, "Sync timer should be set")

        // The environment should be fetched.
        XCTAssertNotNil(Formbricks.surveyManager?.workspaceResponse)

        // Check if the filter method works properly.
        XCTAssertEqual(Formbricks.surveyManager?.filteredSurveys.count, 1)

        // Verify that we're not showing any survey initially.
        XCTAssertNotNil(Formbricks.surveyManager?.filteredSurveys)
        XCTAssertFalse(Formbricks.surveyManager?.isShowingSurvey ?? false)

        // Track an unknown event—survey should not be shown.
        Formbricks.track("unknown_event")
        XCTAssertFalse(Formbricks.surveyManager?.isShowingSurvey ?? false)

        // Track a known event—the survey should be shown.
        let trackExpectation = expectation(description: "Track event")
        Formbricks.track("click_demo_button", completion: {
            trackExpectation.fulfill()
        })

        wait(for: [trackExpectation])

        // In headless test environment, presentation fails (no key window), so flag should reset to false
        XCTAssertFalse(Formbricks.surveyManager?.isShowingSurvey ?? true)

        // "Dismiss" the webview.
        Formbricks.surveyManager?.dismissSurveyWebView()
        XCTAssertFalse(Formbricks.surveyManager?.isShowingSurvey ?? false)

        // Validate display and response.
        Formbricks.surveyManager?.postResponse(surveyId: surveyID)
        Formbricks.surveyManager?.onNewDisplay(surveyId: surveyID)
        XCTAssertEqual(Formbricks.userManager?.responses?.count, 1)
        XCTAssertEqual(Formbricks.userManager?.displays?.count, 1)

        // Track a valid event, but survey should not be shown because a response was already submitted.
        Formbricks.track("click_demo_button")
        let secondTrackExpectation = expectation(description: "Second track event")
        DispatchQueue.main.asyncAfter(deadline: .now() + 3.0) {
            secondTrackExpectation.fulfill()
        }
        wait(for: [secondTrackExpectation], timeout: 5.0)

        XCTAssertFalse(Formbricks.surveyManager?.isShowingSurvey ?? false)

        // Validate logout.
        XCTAssertNotNil(Formbricks.userManager?.userId)
        XCTAssertNotNil(Formbricks.userManager?.responses)
        XCTAssertNotNil(Formbricks.userManager?.displays)
        Formbricks.logout()

        let logoutExpectation = expectation(description: "Logout")
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
            logoutExpectation.fulfill()
        }
        wait(for: [logoutExpectation], timeout: 1.0)

        XCTAssertNil(Formbricks.userManager?.userId)
        XCTAssertNil(Formbricks.userManager?.responses)
        XCTAssertNil(Formbricks.userManager?.displays)

        // Clear the responses and verify survey behavior.
        Formbricks.logout()
        Formbricks.surveyManager?.filterSurveys()

        let thirdTrackExpectation = expectation(description: "Third track event")
        Formbricks.track("click_demo_button", completion: {
            thirdTrackExpectation.fulfill()
        })

        wait(for: [thirdTrackExpectation])

        // In headless test environment, presentation fails (no key window), so flag should reset to false
        XCTAssertFalse(Formbricks.surveyManager?.isShowingSurvey ?? true)

        // Test the cleanup
        Formbricks.cleanup()
        XCTAssertNil(Formbricks.userManager)
        XCTAssertNil(Formbricks.surveyManager)
        XCTAssertNil(Formbricks.apiQueue)
        XCTAssertNil(Formbricks.presentSurveyManager)
        XCTAssertFalse(Formbricks.isInitialized)
        XCTAssertNil(Formbricks.appUrl)
        XCTAssertNil(Formbricks.workspaceId)
        XCTAssertNil(Formbricks.logger)
    }

